// OOP 四大柱完整示範
public abstract class Animal  // 抽象：不能直接 new Animal()
{
    private string _name;  // 封裝：private 欄位

    // 封裝：Property 含驗證邏輯
    public string Name
    {
        get => _name;
        set => _name = string.IsNullOrWhiteSpace(value) ? "Unknown" : value;
    }

    public int Age { get; protected set; }  // protected set：子類可寫，外部唯讀

    public Animal(string name, int age)
    {
        Name = name;
        Age = age;
    }

    // 抽象方法：子類必須實作（隱含 virtual）
    public abstract string MakeSound();

    // virtual 方法：子類可選擇 override
    public virtual string Describe()
    {
        return $"{Name}（{Age} 歲）發出聲音：{MakeSound()}";
    }
}

public class Dog : Animal  // 繼承
{
    public string Breed { get; set; }

    // base(...) 呼叫父建構子
    public Dog(string name, int age, string breed) : base(name, age)
    {
        Breed = breed;
    }

    public override string MakeSound() => "汪汪！";  // 多型：override

    public override string Describe()
    {
        return base.Describe() + $"（品種：{Breed}）";  // base. 呼叫父版本
    }
}

public class Cat : Animal
{
    public Cat(string name, int age) : base(name, age) { }
    public override string MakeSound() => "喵～";
    // 不 override Describe()，使用父類版本
}

// 多型展示：父類型別持有子類實例
List<Animal> animals = new List<Animal>
{
    new Dog("小黑", 3, "拉布拉多"),
    new Cat("咪咪", 2)
};
foreach (Animal a in animals)  // a 的靜態型別是 Animal
{
    Console.WriteLine(a.Describe());  // 執行期呼叫各自的版本
}

