public abstract class Vehicle
{
    private string _brand;

    public string Brand
    {
        get => _brand;
        set => _brand = string.IsNullOrWhiteSpace(value)
            ? throw new ArgumentException("Brand 不可為空")
            : value;
    }

    public Vehicle(string brand)
    {
        Brand = brand;
    }

    public abstract string GetFuelType();

    public virtual string Describe()
    {
        return $"{Brand} 使用 {GetFuelType()} 燃料";
    }
}

public class Car : Vehicle
{
    public Car(string brand) : base(brand) { }

    public override string GetFuelType() => "汽油";

    public override string Describe()
    {
        return base.Describe() + " (4輪轎車)";
    }
}

public class Truck : Vehicle
{
    public Truck(string brand) : base(brand) { }

    public override string GetFuelType() => "柴油";
}

public class BankAccount
{
    private decimal _balance;
    private string _owner;

    public decimal Balance => _balance;  // 唯讀屬性
    public string Owner => _owner;

    public BankAccount(string owner, decimal initialBalance)
    {
        if (string.IsNullOrWhiteSpace(owner))
            throw new ArgumentException("帳戶持有人不可為空");
        if (initialBalance < 0)
            throw new ArgumentException("初始金額不可為負數");

        _owner = owner;
        _balance = initialBalance;
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentException("存款金額必須大於零");
        _balance += amount;
    }

    public bool Withdraw(decimal amount)
    {
        if (amount <= 0 || amount > _balance)
            return false;
        _balance -= amount;
        return true;
    }

    public override string ToString()
    {
        return $"帳戶：{_owner}，餘額：{_balance:C}";
    }
}

public abstract class Shape
{
    public abstract double Area();
    public abstract double Perimeter();

    public override string ToString()
    {
        return $"{GetType().Name}: 面積={Area():F2}, 周長={Perimeter():F2}";
    }
}

public class Circle : Shape
{
    public double Radius { get; }
    public Circle(double radius) { Radius = radius; }

    public override double Area() => Math.PI * Radius * Radius;
    public override double Perimeter() => 2 * Math.PI * Radius;
}

public class Rectangle : Shape
{
    public double Width { get; }
    public double Height { get; }
    public Rectangle(double width, double height)
    {
        Width = width;
        Height = height;
    }
    public override double Area() => Width * Height;
    public override double Perimeter() => 2 * (Width + Height);
}

// 使用程式
List<Shape> shapes = new List<Shape>
{
    new Circle(5),
    new Rectangle(4, 6),
    new Circle(3)
};

foreach (Shape s in shapes)
{
    Console.WriteLine(s.ToString());
}

Shape largest = shapes[0];
foreach (Shape s in shapes)
{
    if (s.Area() > largest.Area())
        largest = s;
}
Console.WriteLine($"最大面積：{largest}");

public class Employee
{
    public string Name { get; set; }
    public decimal Salary { get; set; }

    public Employee(string name, decimal salary)
    {
        Name = name;
        Salary = salary;
    }

    public virtual decimal CalculatePay()
    {
        return Salary;
    }

    public override string ToString()
    {
        return $"{Name}，薪資：{CalculatePay():C}";
    }
}

public class Manager : Employee
{
    private int _teamSize;

    public int TeamSize
    {
        get => _teamSize;
        set => _teamSize = value < 0 ? 0 : value;
    }

    public Manager(string name, decimal salary, int teamSize)
        : base(name, salary)  // 呼叫父建構子
    {
        TeamSize = teamSize;
    }

    public override decimal CalculatePay()
    {
        return base.CalculatePay() + (TeamSize * 1000m);  // base. 複用父邏輯
    }

    public override string ToString()
    {
        return $"{Name}（主管），薪資：{CalculatePay():C}，團隊：{TeamSize} 人";
    }
}

public class Logger
{
    public virtual void Log(string msg)
    {
        Console.WriteLine($"[LOG] {msg}");
    }
}

public class FileLogger : Logger
{
    private string _filePath;

    public FileLogger(string filePath)
    {
        _filePath = filePath;
    }

    // sealed 阻止更下層的子類 override
    public sealed override void Log(string msg)
    {
        Console.WriteLine($"[FILE:{_filePath}] {msg}");
        // 實際實作：File.AppendAllText(_filePath, msg);
    }
}

public class SpecialFileLogger : FileLogger
{
    public SpecialFileLogger(string path) : base(path) { }

    // 以下會造成 CS0239 編譯錯誤：
    // public override void Log(string msg)  // 錯誤！Log 已被 sealed
    // {
    //     base.Log(msg);
    // }

    // 可以新增其他方法，但不能 override sealed 的 Log()
    public void LogWithTimestamp(string msg)
    {
        Log($"[{DateTime.Now:HH:mm:ss}] {msg}");  // 呼叫繼承來的 sealed Log()
    }
}

public class GameCharacter
{
    protected int _hp;
    protected int _maxHp;

    public int HP => _hp;  // 外部唯讀
    public string Name { get; protected set; }  // 子類可寫

    public GameCharacter(string name, int maxHp)
    {
        Name = name;
        _maxHp = maxHp;
        _hp = maxHp;
    }

    protected virtual void TakeDamage(int dmg)
    {
        _hp = Math.Max(0, _hp - dmg);  // 不低於 0
    }

    public void Attack(GameCharacter target, int damage)
    {
        target.TakeDamage(damage);
        Console.WriteLine($"{Name} 攻擊 {target.Name}，造成 {damage} 傷害");
    }

    public bool IsAlive => _hp > 0;
}

public class Warrior : GameCharacter
{
    public int Armor { get; set; }

    public Warrior(string name, int maxHp, int armor)
        : base(name, maxHp)
    {
        Armor = armor;
    }

    protected override void TakeDamage(int dmg)
    {
        // 護甲減傷：護甲值越高，減傷越多（最多減 80%）
        double reduction = Math.Min(0.8, Armor / 100.0);
        int actualDmg = (int)(dmg * (1 - reduction));
        base.TakeDamage(actualDmg);  // 呼叫父類扣血邏輯
        Console.WriteLine($"護甲減傷 {dmg - actualDmg} 點");
    }
}

public abstract class Animal
{
    public string Name { get; set; }
    public Animal(string name) { Name = name; }
    public abstract string MakeSound();
}

public class Dog : Animal
{
    public Dog(string name) : base(name) { }
    public override string MakeSound() => "汪！";
    public string Fetch() => $"{Name} 去撿球了！";
}

public class Cat : Animal
{
    public Cat(string name) : base(name) { }
    public override string MakeSound() => "喵！";
    public string Purr() => $"{Name} 發出呼嚕聲";
}

// 使用程式
Animal[] animals = new Animal[]  // 向上轉型（upcasting）
{
    new Dog("小黑"),
    new Cat("咪咪"),
    new Dog("小白")
};

foreach (Animal a in animals)
{
    Console.WriteLine(a.MakeSound());  // 多型

    // 方法一：is 運算子安全檢查
    if (a is Dog dog)
    {
        Console.WriteLine(dog.Fetch());  // 向下轉型（downcasting）
    }

    // 方法二：as 運算子（失敗回傳 null）
    Cat cat = a as Cat;
    if (cat != null)
    {
        Console.WriteLine(cat.Purr());
    }
}

