// ── 介面：定義跨類別的行為契約 ──
public interface IPayable
{
    decimal GetPayAmount();  // 隱含 public abstract
    string PaymentDescription => $"付款金額：{GetPayAmount():C}";  // C# 8+ default 實作
}

public interface ILoggable
{
    void Log(string message);
}

// ── 抽象類別：共享狀態與部分實作 ──
public abstract class Employee
{
    // 抽象類別可以有欄位和建構子
    private string _name;
    public string Name
    {
        get => _name;
        set => _name = string.IsNullOrWhiteSpace(value) ? "Unknown" : value;
    }
    protected decimal _baseSalary;

    public Employee(string name, decimal baseSalary)
    {
        Name = name;
        _baseSalary = baseSalary;
    }

    public abstract decimal CalculatePay();  // 子類必須實作

    public virtual string GetTitle() => "員工";  // 子類可選擇 override
}

// ── 類別可以繼承一個抽象類別 + 實作多個介面 ──
public class SalariedEmployee : Employee, IPayable, ILoggable
{
    public SalariedEmployee(string name, decimal salary)
        : base(name, salary) { }

    public override decimal CalculatePay() => _baseSalary;

    // IPayable 實作
    public decimal GetPayAmount() => CalculatePay();

    // ILoggable 實作
    public void Log(string message)
        => Console.WriteLine($"[{Name}] {message}");
}

public class CommissionEmployee : Employee, IPayable
{
    public decimal CommissionRate { get; set; }
    public decimal GrossSales { get; set; }

    public CommissionEmployee(string name, decimal rate, decimal sales)
        : base(name, 0) { CommissionRate = rate; GrossSales = sales; }

    public override decimal CalculatePay() => GrossSales * CommissionRate;
    public decimal GetPayAmount() => CalculatePay();
    public override string GetTitle() => "業務員";
}

// IPayable 介面多型：不同類別透過共同介面操作
List<IPayable> payables = new List<IPayable> { new SalariedEmployee("王小明", 50000), new CommissionEmployee("李大華", 0.1m, 300000) };
foreach (IPayable p in payables)
    Console.WriteLine(p.PaymentDescription);

