public interface IShape
{
    double Area();
    double Perimeter();
    string ShapeType { get; }  // 唯讀屬性
}

public class Circle : IShape
{
    public double Radius { get; }
    public Circle(double radius) { Radius = radius; }

    public double Area() => Math.PI * Radius * Radius;
    public double Perimeter() => 2 * Math.PI * Radius;
    public string ShapeType => "圓形";
}

public class Rectangle : IShape
{
    public double Width { get; }
    public double Height { get; }
    public Rectangle(double w, double h) { Width = w; Height = h; }

    public double Area() => Width * Height;
    public double Perimeter() => 2 * (Width + Height);
    public string ShapeType => "矩形";
}

public static void PrintShapeInfo(IShape shape)
{
    Console.WriteLine($"類型：{shape.ShapeType}");
    Console.WriteLine($"面積：{shape.Area():F2}");
    Console.WriteLine($"周長：{shape.Perimeter():F2}");
    Console.WriteLine();
}

// 使用
PrintShapeInfo(new Circle(5));
PrintShapeInfo(new Rectangle(4, 6));

public class Student : IComparable<Student>
{
    public string Name { get; set; }
    public double GPA { get; set; }

    public Student(string name, double gpa)
    {
        Name = name;
        GPA = gpa;
    }

    // IComparable<T> 要求實作此方法
    // 回傳負數：this 排在 other 前面
    // 回傳 0：相等
    // 回傳正數：this 排在 other 後面
    public int CompareTo(Student? other)
    {
        if (other == null) return 1;
        // 由高到低：other 和 this 順序對調
        return other.GPA.CompareTo(this.GPA);
    }

    public override string ToString() => $"{Name}：GPA {GPA:F2}";
}

// 測試
List<Student> students = new List<Student>
{
    new Student("小明", 3.5),
    new Student("小華", 3.8),
    new Student("小英", 3.2),
    new Student("小強", 3.8)
};

students.Sort();  // 呼叫 IComparable<Student>.CompareTo
foreach (Student s in students)
    Console.WriteLine(s);

public interface IFlyable
{
    void Fly();
    int MaxAltitude { get; }  // 最大飛行高度（公尺）
}

public interface ISwimmable
{
    void Swim();
    int MaxDepth { get; }  // 最大潛水深度（公尺）
}

public class Eagle : IFlyable
{
    public string Name { get; set; }
    public Eagle(string name) { Name = name; }

    public void Fly() => Console.WriteLine($"{Name} 展翅高飛！");
    public int MaxAltitude => 3000;
}

public class Penguin : IFlyable, ISwimmable  // 同時實作兩個介面
{
    public string Name { get; set; }
    public Penguin(string name) { Name = name; }

    // 企鵝不會飛，但實作 IFlyable
    public void Fly() => throw new NotSupportedException($"{Name} 不會飛！");
    public int MaxAltitude => 0;

    public void Swim() => Console.WriteLine($"{Name} 在水中游泳！");
    public int MaxDepth => 500;
}

// 介面作為參數型別（多型）
public static void MakeItFly(IFlyable f)
{
    try
    {
        Console.WriteLine($"最大飛行高度：{f.MaxAltitude} 公尺");
        f.Fly();
    }
    catch (NotSupportedException ex)
    {
        Console.WriteLine($"無法飛行：{ex.Message}");
    }
}

// 測試
MakeItFly(new Eagle("老鷹"));
MakeItFly(new Penguin("企鵝"));

public interface ILogger
{
    void Info(string msg);
    void Error(string msg);

    // C# 8+ default interface method
    void Warning(string msg)
    {
        // 預設實作：所有實作類別若未 override，使用此版本
        Console.WriteLine($"[WARNING] {msg}");
    }
}

public class ConsoleLogger : ILogger
{
    public void Info(string msg) => Console.WriteLine($"[INFO] {msg}");
    public void Error(string msg) => Console.WriteLine($"[ERROR] {msg}");

    // 覆寫 default 實作
    public void Warning(string msg) => Console.WriteLine($"[WARN ⚠] {msg}");
}

public class FileLogger : ILogger
{
    private string _path;
    public FileLogger(string path) { _path = path; }

    public void Info(string msg)
        => Console.WriteLine($"[FILE-INFO:{_path}] {msg}");

    public void Error(string msg)
        => Console.WriteLine($"[FILE-ERROR:{_path}] {msg}");

    // 未 override Warning，使用介面的 default 實作
}

// 測試
ILogger console = new ConsoleLogger();
ILogger file = new FileLogger("/var/log/app.log");

console.Warning("磁碟空間不足");  // [WARN ⚠] 磁碟空間不足（ConsoleLogger 自己的版本）
