// 抽象類別：提供共用狀態和實作（同類型物件共享邏輯）
public abstract class Animal
{
    public string Name { get; set; }
    protected int _energy;

    public Animal(string name)
    {
        Name = name;
        _energy = 100;
    }

    // 已實作的共用方法
    public void Eat(string food)
    {
        _energy += 10;
        Console.WriteLine($"{Name} 吃了 {food}，體力：{_energy}");
    }

    public abstract string MakeSound();  // 各子類不同
}

// 介面：跨類別的行為契約（可馴養性與 Animal 無必然關係）
public interface IDomesticatable
{
    void BeTrained(string command);
    int TrainingLevel { get; }
}

public class Dog : Animal, IDomesticatable
{
    public int TrainingLevel { get; private set; }

    public Dog(string name) : base(name) { TrainingLevel = 0; }

    public override string MakeSound() => "汪汪！";

    public void BeTrained(string command)
    {
        TrainingLevel++;
        Console.WriteLine($"{Name} 學會了指令：{command}（訓練等級 {TrainingLevel}）");
    }
}

public class Wolf : Animal
{
    public Wolf(string name) : base(name) { }
    public override string MakeSound() => "嚎叫！";
    // 狼不實作 IDomesticatable
}

// 測試
List<Animal> animals = new List<Animal> { new Dog("小黑"), new Wolf("灰太狼"), new Dog("小白") };
foreach (Animal a in animals)
{
    a.Eat("肉");
    if (a is IDomesticatable trainable)  // 只有 Dog 會進入
        trainable.BeTrained("坐下");
}

