// 泛型類別：型別安全的 Stack
public class Stack<T>
{
    private T[] _items;
    private int _top;

    public Stack(int capacity = 16)
    {
        _items = new T[capacity];
        _top = -1;
    }

    public bool IsEmpty => _top < 0;
    public int Count => _top + 1;

    public void Push(T item)
    {
        if (_top >= _items.Length - 1)
            throw new InvalidOperationException("Stack 已滿");
        _items[++_top] = item;
    }

    public T Pop()
    {
        if (IsEmpty) throw new InvalidOperationException("Stack 為空");
        T item = _items[_top];
        _items[_top--] = default!;  // 清除參考，協助 GC
        return item;
    }

    public T Peek()
    {
        if (IsEmpty) throw new InvalidOperationException("Stack 為空");
        return _items[_top];
    }
}

// 帶型別約束的泛型方法
public static T Max<T>(T a, T b) where T : IComparable<T>
{
    return a.CompareTo(b) >= 0 ? a : b;
}

// 使用
Stack<int> intStack = new Stack<int>();
intStack.Push(1); intStack.Push(2); intStack.Push(3);
Console.WriteLine(intStack.Pop());  // 3

Stack<string> strStack = new Stack<string>();
strStack.Push("hello"); strStack.Push("world");
Console.WriteLine(strStack.Peek());  // world

// 型別約束：可呼叫 CompareTo()
Console.WriteLine(Max(3, 7));        // 7
Console.WriteLine(Max("apple", "banana"));  // banana

