public class Stack<T>
{
    private List<T> _items = new List<T>();

    public bool IsEmpty => _items.Count == 0;
    public int Count => _items.Count;

    public void Push(T item)
    {
        _items.Add(item);  // 加到末端（頂部）
    }

    public T Pop()
    {
        if (IsEmpty)
            throw new InvalidOperationException("Stack 為空，無法 Pop");

        T item = _items[_items.Count - 1];
        _items.RemoveAt(_items.Count - 1);
        return item;
    }

    public T Peek()
    {
        if (IsEmpty)
            throw new InvalidOperationException("Stack 為空，無法 Peek");

        return _items[_items.Count - 1];
    }

    public override string ToString()
        => $"Stack<{typeof(T).Name}>[{string.Join(", ", _items)}]（頂部在右）";
}

// 測試
Stack<int> s = new Stack<int>();
s.Push(10); s.Push(20); s.Push(30);
Console.WriteLine(s.Peek());   // 30
Console.WriteLine(s.Pop());    // 30
Console.WriteLine(s.Count);    // 2

public static void Swap<T>(ref T a, ref T b)
{
    T temp = a;
    a = b;
    b = temp;
}

public static void Reverse<T>(T[] arr)
{
    int left = 0;
    int right = arr.Length - 1;
    while (left < right)
    {
        Swap(ref arr[left], ref arr[right]);  // 型別推斷，不需寫 Swap<T>
        left++;
        right--;
    }
}

// 測試
int x = 5, y = 10;
Swap(ref x, ref y);  // 型別推斷為 int
Console.WriteLine($"x={x}, y={y}");  // x=10, y=5

int[] nums = { 1, 2, 3, 4, 5 };
Reverse(nums);
Console.WriteLine(string.Join(", ", nums));  // 5, 4, 3, 2, 1

string[] words = { "apple", "banana", "cherry" };
Reverse(words);
Console.WriteLine(string.Join(", ", words));  // cherry, banana, apple

public static T FindMax<T>(IEnumerable<T> items) where T : IComparable<T>
{
    T? max = default;
    bool first = true;

    foreach (T item in items)
    {
        if (first)
        {
            max = item;
            first = false;
        }
        else if (item.CompareTo(max!) > 0)  // 正數表示 item > max
        {
            max = item;
        }
    }

    if (first)  // 集合是空的
        throw new ArgumentException("集合不能為空");

    return max!;
}

public static T FindMin<T>(IEnumerable<T> items) where T : IComparable<T>
{
    T? min = default;
    bool first = true;

    foreach (T item in items)
    {
        if (first) { min = item; first = false; }
        else if (item.CompareTo(min!) < 0)  // 負數表示 item < min
            min = item;
    }

    if (first) throw new ArgumentException("集合不能為空");
    return min!;
}

// 測試
int[] nums = { 3, 1, 4, 1, 5, 9, 2, 6 };
Console.WriteLine(FindMax(nums));   // 9
Console.WriteLine(FindMin(nums));   // 1

string[] words = { "banana", "apple", "cherry" };
Console.WriteLine(FindMax(words));  // cherry（字典序最大）
Console.WriteLine(FindMin(words));  // apple

public class Pair<TFirst, TSecond>
{
    public TFirst First { get; }
    public TSecond Second { get; }

    public Pair(TFirst first, TSecond second)
    {
        First = first;
        Second = second;
    }

    // 靜態工廠方法（利用型別推斷，呼叫時不需指定型別參數）
    public static Pair<TFirst, TSecond> Create(TFirst first, TSecond second)
        => new Pair<TFirst, TSecond>(first, second);

    public override string ToString()
        => $"({First}, {Second})";
}

public static Pair<T2, T1> SwapPair<T1, T2>(Pair<T1, T2> p)
{
    return new Pair<T2, T1>(p.Second, p.First);
}

// 測試
var p1 = new Pair<string, int>("年齡", 25);
Console.WriteLine(p1);  // (年齡, 25)

var p2 = Pair<int, bool>.Create(42, true);  // 工廠方法
Console.WriteLine(p2);  // (42, True)

var swapped = SwapPair(p1);  // 型別推斷為 Pair<int, string>
Console.WriteLine(swapped);  // (25, 年齡)

// where T : new() 允許在泛型方法中呼叫 new T()
public static T CreateInstance<T>() where T : new()
{
    return new T();  // 沒有 new() 約束就無法這樣寫
}

public static List<T> CreateList<T>(int count) where T : new()
{
    if (count < 0) throw new ArgumentOutOfRangeException(nameof(count));

    List<T> list = new List<T>(count);
    for (int i = 0; i < count; i++)
    {
        list.Add(new T());  // 每次建立新實例
    }
    return list;
}

