public class Queue<T>
{
    private List<T> _items = new List<T>();

    public bool IsEmpty => _items.Count == 0;

    public void Enqueue(T item) => _items.Add(item);  // 加入末端（正確）

    public T Dequeue()
    {
        if (IsEmpty) throw new InvalidOperationException("Queue 為空");
        // [修正] Queue 是 FIFO，從前端（索引 0）取出
        T item = _items[0];
        _items.RemoveAt(0);
        return item;
    }

    public T Peek()
    {
        if (IsEmpty) throw new InvalidOperationException("Queue 為空");
        return _items[0];  // [修正] 查看前端
    }
}

