// ── 4. 標準 EventHandler 模式 ──
public class TemperatureChangedEventArgs : EventArgs
{
    public double OldTemp { get; }
    public double NewTemp { get; }
    public TemperatureChangedEventArgs(double old, double @new)
    { OldTemp = old; NewTemp = @new; }
}

public class Thermometer
{
    private double _temp;
    // event 保護：外部只能 += / -=，不能直接呼叫或 =
    public event EventHandler<TemperatureChangedEventArgs>? TemperatureChanged;

    public double Temperature
    {
        get => _temp;
        set
        {
            if (value != _temp)
            {
                double old = _temp;
                _temp = value;
                // ?. 確保有訂閱者才觸發，避免 NullReferenceException
                TemperatureChanged?.Invoke(this, new TemperatureChangedEventArgs(old, value));
            }
        }
    }
}

// 訂閱事件
Thermometer t = new Thermometer();
t.TemperatureChanged += (sender, e)
    => Console.WriteLine($"溫度從 {e.OldTemp}°C 變為 {e.NewTemp}°C");
t.Temperature = 36.5;  // 觸發事件

