// 事件發佈者（Publisher）
public class Button
{
    private int _clickCount = 0;
    public string Name { get; set; }

    public Button(string name) { Name = name; }

    // event 修飾：外部只能 += / -=
    public event EventHandler<ButtonClickEventArgs>? Clicked;

    public void Click()
    {
        _clickCount++;
        // ?. 避免 Clicked 為 null 時拋出例外
        Clicked?.Invoke(this, new ButtonClickEventArgs(_clickCount));
    }
}

// 事件訂閱者（Subscriber）
public class ClickLogger
{
    public void OnButtonClicked(object? sender, ButtonClickEventArgs e)
    {
        Button? btn = sender as Button;
        Console.WriteLine($"[{e.ClickTime:HH:mm:ss}] {btn?.Name} 被點擊第 {e.ClickCount} 次");
    }
}

// 測試
Button btn = new Button("確認");
ClickLogger logger = new ClickLogger();

btn.Clicked += logger.OnButtonClicked;  // 訂閱
btn.Clicked += (s, e) => Console.WriteLine($"  → 匿名訂閱者：總點擊 {e.ClickCount}");

btn.Click();  // 點擊 3 次
btn.Click();
btn.Click();

btn.Clicked -= logger.OnButtonClicked;  // 取消訂閱
btn.Click();  // 只有匿名訂閱者收到

