public class EventBroker
{
    // 多播 Action：可同時通知多個訂閱者
    public Action<string>? OnOrderPlaced { get; set; }

    public void NotifyOrderPlaced(string orderInfo)
    {
        OnOrderPlaced?.Invoke(orderInfo);
    }
}

public class OrderService
{
    private readonly EventBroker _broker;
    private int _orderCount = 0;

    public OrderService(EventBroker broker) { _broker = broker; }

    public void PlaceOrder(string product)
    {
        _orderCount++;
        Console.WriteLine($"[訂單服務] 建立訂單 #{_orderCount}：{product}");
        _broker.NotifyOrderPlaced($"訂單 #{_orderCount} - {product}");
    }
}

public class EmailService
{
    public void SendOrderConfirmation(string orderInfo)
        => Console.WriteLine($"[Email] 寄送確認信：{orderInfo}");
}

public class SmsService
{
    public void SendSms(string orderInfo)
        => Console.WriteLine($"[SMS] 發送簡訊：{orderInfo}");
}

// 組裝
EventBroker broker = new EventBroker();
OrderService orders = new OrderService(broker);
EmailService email = new EmailService();
