public static void Sort<T>(T[] arr, Func<T, T, int> comparer)
{
    // 氣泡排序
    for (int i = 0; i < arr.Length - 1; i++)
    {
        for (int j = 0; j < arr.Length - 1 - i; j++)
        {
            if (comparer(arr[j], arr[j + 1]) > 0)  // 委派決定排序邏輯
            {
                T temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

