public class PriceAlertEventArgs : EventArgs
{
    public decimal OldPrice { get; }
    public decimal NewPrice { get; }
    public string AlertType { get; }  // "HIGH" 或 "LOW"

    public PriceAlertEventArgs(decimal old, decimal @new, string alertType)
    {
        OldPrice = old; NewPrice = @new; AlertType = alertType;
    }
}

public class StockMonitor
{
    private decimal _price;
    public decimal HighThreshold { get; set; }  // 高價警戒
    public decimal LowThreshold { get; set; }   // 低價警戒
    public string Symbol { get; }

    public event EventHandler<PriceAlertEventArgs>? PriceRaisedAlert;
    public event EventHandler<PriceAlertEventArgs>? PriceDroppedAlert;

    public StockMonitor(string symbol, decimal high, decimal low)
    {
        Symbol = symbol; HighThreshold = high; LowThreshold = low;
    }

    public decimal Price
    {
        get => _price;
        set
        {
            decimal old = _price;
            _price = value;

            if (value > HighThreshold)
                PriceRaisedAlert?.Invoke(this,
                    new PriceAlertEventArgs(old, value, "HIGH"));
            else if (value < LowThreshold)
                PriceDroppedAlert?.Invoke(this,
                    new PriceAlertEventArgs(old, value, "LOW"));
        }
    }
}

// 測試
StockMonitor tsmc = new StockMonitor("2330", 1000m, 800m);

tsmc.PriceRaisedAlert  += (s, e) =>
    Console.WriteLine($"⚠ 高價警示！{((StockMonitor)s).Symbol}：{e.OldPrice}→{e.NewPrice}");
tsmc.PriceDroppedAlert += (s, e) =>
    Console.WriteLine($"⚠ 低價警示！{((StockMonitor)s).Symbol}：{e.OldPrice}→{e.NewPrice}");

tsmc.Price = 950m;   // 無警示
tsmc.Price = 1050m;  // 觸發 PriceRaisedAlert
tsmc.Price = 790m;   // 觸發 PriceDroppedAlert

