    };

// ── 對應關係表 ──
// 方法語法               查詢語法
// .Where(pred)        ←→  where pred
// .Select(proj)       ←→  select proj
// .OrderBy(key)       ←→  orderby key
// .OrderByDescending  ←→  orderby key descending
// .GroupBy(key)       ←→  group x by key
// .Join(...)          ←→  join ... on ... equals ...
// （無查詢語法對應）   ←→  SelectMany, Aggregate, Skip, Take

