// ── 基本 async/await ──
public async Task<string> FetchDataAsync(string url)
{
    using HttpClient client = new HttpClient();
    // await 不阻塞執行緒，等待 HTTP 回應期間可處理其他工作
    string content = await client.GetStringAsync(url);
    return content.Substring(0, Math.Min(100, content.Length));
}

// ── Task.WhenAll 並行執行 ──
public async Task<int[]> FetchMultipleAsync()
{
    Task<int> t1 = Task.Run(() => { Task.Delay(1000).Wait(); return 1; });
    Task<int> t2 = Task.Run(() => { Task.Delay(500).Wait();  return 2; });
    Task<int> t3 = Task.Run(() => { Task.Delay(800).Wait();  return 3; });

    // 三個同時跑，等所有完成（約 1 秒，不是 2.3 秒）
    int[] results = await Task.WhenAll(t1, t2, t3);
    return results;  // [1, 2, 3]
}

// ── CancellationToken ──
public async Task ProcessLargeFileAsync(string path, CancellationToken token)
{
    var lines = File.ReadAllLines(path);
    for (int i = 0; i < lines.Length; i++)
    {
        token.ThrowIfCancellationRequested();  // 每次迴圈檢查取消
        await Task.Delay(10, token);           // 模擬處理，支援取消
        Console.WriteLine($"處理第 {i + 1} 行");
    }
}

// 使用
var cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
try
{
    await ProcessLargeFileAsync("data.txt", cts.Token);
}
catch (OperationCanceledException)
{
    Console.WriteLine("處理被取消");
}

