public class Calculator
{
    // async Task<T>：非同步方法有回傳值
    public async Task<int> SumAsync(int[] numbers)
    {
        // 模擬非同步 IO 操作（如讀取資料庫）
        await Task.Delay(100);

        // 計算完畢後回傳（await 之後繼續執行）
        int sum = 0;
        foreach (int n in numbers)
            sum += n;
        return sum;
    }

    // 另一種寫法：用 LINQ
    public async Task<int> SumLinqAsync(int[] numbers)
    {
        await Task.Delay(100);
        return numbers.Sum();
    }
}

// async Task Main（C# 7.1+ 支援）
public static async Task Main(string[] args)
{
    var calc = new Calculator();
    int[] numbers = { 1, 2, 3, 4, 5 };

    // await 等待 Task<int> 完成，取得 int 結果
    int result = await calc.SumAsync(numbers);
    Console.WriteLine($"總和：{result}");  // 15

    // 也可以先拿 Task 再 await
    Task<int> task = calc.SumLinqAsync(numbers);
    // 可在此期間做其他事...
    int result2 = await task;
    Console.WriteLine($"LINQ 總和：{result2}");  // 15
}

// 模擬 HTTP 請求（實際用 HttpClient.GetStringAsync）
private static async Task<string> FakeHttpGetAsync(string url, int delayMs)
{
    await Task.Delay(delayMs);
    return $"{url}_content";
}

// ── 版本一：循序執行（慢，total = sum of delays）──
public static async Task<List<string>> FetchSequentialAsync(List<string> urls)
{
    var results = new List<string>();
    foreach (string url in urls)
    {
        // 一個 await 完成才進行下一個
        string content = await FakeHttpGetAsync(url, 500);
        results.Add(content);
    }
    return results;  // 3 個 URL × 500ms = ~1500ms
}

// ── 版本二：並行執行（快，total = max of delays）──
public static async Task<List<string>> FetchParallelAsync(List<string> urls)
{
    // 先建立所有 Task（不 await，讓它們同時開始執行）
    IEnumerable<Task<string>> tasks = urls.Select(url => FakeHttpGetAsync(url, 500));

    // 等待全部完成（約 500ms，不是 1500ms）
    string[] results = await Task.WhenAll(tasks);
    return results.ToList();
}

// 測試
static async Task Main()
{
    var urls = new List<string> { "url1", "url2", "url3" };

    var sw = System.Diagnostics.Stopwatch.StartNew();
    var seq = await FetchSequentialAsync(urls);
    Console.WriteLine($"循序：{sw.ElapsedMilliseconds}ms");  // ~1500ms

    sw.Restart();
    var par = await FetchParallelAsync(urls);
    Console.WriteLine($"並行：{sw.ElapsedMilliseconds}ms");  // ~500ms
}

public static async Task DownloadWithTimeoutAsync(string fileName, CancellationToken token)
{
    Console.WriteLine($"開始下載：{fileName}");

    for (int block = 1; block <= 10; block++)
    {
        // 方式一：將 token 傳給支援取消的方法
        await Task.Delay(200, token);

        // 方式二：手動檢查取消（適合 CPU-bound 工作）
        token.ThrowIfCancellationRequested();

        Console.WriteLine($"  [{fileName}] 下載區塊 {block}/10");
    }

    Console.WriteLine($"下載完成：{fileName}");
}

static async Task Main()
{
    // 建立 CancellationTokenSource，1.5 秒後自動取消
    using var cts = new CancellationTokenSource();
    cts.CancelAfter(TimeSpan.FromSeconds(1.5));

    try
    {
        await DownloadWithTimeoutAsync("report.pdf", cts.Token);
    }
    catch (OperationCanceledException)
    {
        // await 的 Task 被取消時拋出 OperationCanceledException
        Console.WriteLine("下載已取消（超過時限）");
    }
    finally
    {
        Console.WriteLine("清理資源...");
    }

    // 也可以手動取消
    using var cts2 = new CancellationTokenSource();
    var downloadTask = DownloadWithTimeoutAsync("data.zip", cts2.Token);
    await Task.Delay(500);
    cts2.Cancel();  // 手動取消
    try { await downloadTask; }
    catch (OperationCanceledException) { Console.WriteLine("手動取消成功"); }
}

public static async Task<T> WithTimeoutAsync<T>(Task<T> task, TimeSpan timeout)
{
    // 建立一個計時 Task
    Task delayTask = Task.Delay(timeout);

    // WhenAny：誰先完成就繼續
    Task completedTask = await Task.WhenAny(task, delayTask);

    if (completedTask == delayTask)
    {
        // 超時的是計時 Task，原始 task 尚未完成
        throw new TimeoutException($"操作超過 {timeout.TotalSeconds} 秒未完成");
    }

    // 原始 task 先完成：await 它以取得結果（或重新拋出例外）
    return await task;
}

// 模擬慢速操作
private static async Task<string> SlowOperationAsync(int delayMs)
{
    await Task.Delay(delayMs);
    return $"完成（耗時 {delayMs}ms）";
}

static async Task Main()
{
    try
    {
        // 操作 500ms，timeout 2 秒 → 成功
        string r1 = await WithTimeoutAsync(SlowOperationAsync(500), TimeSpan.FromSeconds(2));
        Console.WriteLine(r1);

        // 操作 3000ms，timeout 1 秒 → 超時
        string r2 = await WithTimeoutAsync(SlowOperationAsync(3000), TimeSpan.FromSeconds(1));
        Console.WriteLine(r2);
    }
    catch (TimeoutException ex)
    {
        Console.WriteLine($"逾時：{ex.Message}");
    }
}

private static async Task<string> WorkAsync(int id, bool shouldFail)
{
    await Task.Delay(100 * id);
    if (shouldFail)
        throw new Exception($"Task {id} 失敗了！");
    return $"Task {id} 成功";
}

static async Task Main()
{
    Task<string> t1 = WorkAsync(1, shouldFail: false);
    Task<string> t2 = WorkAsync(2, shouldFail: true);   // 會失敗
    Task<string> t3 = WorkAsync(3, shouldFail: true);   // 也會失敗

    // ── 方法一：只捕捉第一個例外（常見但不完整）──
    try
    {
        string[] results = await Task.WhenAll(t1, t2, t3);
    }
    catch (Exception ex)
    {
        // 只收到第一個拋出的例外
        Console.WriteLine($"第一個例外：{ex.Message}");
    }

    // ── 方法二：檢查所有 Task 的例外 ──
    Task<string> a1 = WorkAsync(1, false);
    Task<string> a2 = WorkAsync(2, true);
    Task<string> a3 = WorkAsync(3, true);

    Task allTasks = Task.WhenAll(a1, a2, a3);
    try
    {
        await allTasks;
    }
    catch
    {
        // allTasks.Exception 包含所有失敗 Task 的 AggregateException
        if (allTasks.Exception != null)
        {
            foreach (Exception inner in allTasks.Exception.InnerExceptions)
                Console.WriteLine($"例外：{inner.Message}");
        }

        // 個別檢查每個 Task 的狀態
        foreach (var t in new[] { a1, a2, a3 })
        {
            if (t.IsFaulted)
                Console.WriteLine($"失敗：{t.Exception!.InnerException!.Message}");
            else if (t.IsCompletedSuccessfully)
                Console.WriteLine($"成功：{t.Result}");
        }
    }
}

public static async Task<T> RetryAsync<T>(
    Func<Task<T>> operation,  // 要執行的非同步操作
    int maxRetries,
    TimeSpan delay)
{
    Exception? lastException = null;

    for (int attempt = 1; attempt <= maxRetries; attempt++)
    {
        try
        {
            T result = await operation();  // 呼叫 Func 取得 Task，再 await
            return result;  // 成功就直接回傳
        }
        catch (Exception ex)
        {
            lastException = ex;
            Console.WriteLine($"第 {attempt} 次嘗試失敗：{ex.Message}");

            if (attempt < maxRetries)
                await Task.Delay(delay);  // 等待後重試
        }
    }

    // 所有重試都失敗
    throw new Exception($"操作在 {maxRetries} 次重試後仍失敗", lastException);
}

// 測試
static int _callCount = 0;
static async Task<string> UnreliableApiAsync()
{
    await Task.Delay(100);
    _callCount++;
    if (_callCount < 3)  // 前兩次失敗，第三次成功
        throw new HttpRequestException($"連線失敗（第 {_callCount} 次）");
    return "API 回應成功";
}

static async Task Main()
{
    try
    {
        string result = await RetryAsync(
            () => UnreliableApiAsync(),  // Func<Task<string>>
            maxRetries: 3,
            delay: TimeSpan.FromMilliseconds(500));
        Console.WriteLine(result);  // API 回應成功
    }
    catch (Exception ex)
    {
        Console.WriteLine($"最終失敗：{ex.Message}");
    }
}

