public static int ParsePositiveInt(string? input)
{
    if (string.IsNullOrWhiteSpace(input))
        throw new ArgumentNullException(nameof(input), "輸入不可為空");

    if (!int.TryParse(input, out int value))
        throw new FormatException($"無法將 '{input}' 解析為整數");

    if (value <= 0)
        throw new ArgumentOutOfRangeException(nameof(input), value, "值必須大於零");

    return value;
}

