// 自訂例外層次結構
public class ValidationException : Exception
{
    public ValidationException(string message) : base(message) { }
    public ValidationException(string message, Exception inner) : base(message, inner) { }
}

public class RequiredFieldException : ValidationException
{
    public string FieldName { get; }

    public RequiredFieldException(string fieldName)
        : base($"欄位 '{fieldName}' 為必填")
    {
        FieldName = fieldName;
    }
}

public class ValueRangeException : ValidationException
{
    public string FieldName { get; }
    public int Min { get; }
    public int Max { get; }

    public ValueRangeException(string fieldName, int min, int max, int actual)
        : base($"欄位 '{fieldName}' 的值 {actual} 不在允許範圍 [{min}, {max}]")
    {
        FieldName = fieldName; Min = min; Max = max;
    }
}

public static void ValidateAge(int? age)
{
    if (age == null)
        throw new RequiredFieldException("年齡");
    if (age < 0 || age > 150)
        throw new ValueRangeException("年齡", 0, 150, age.Value);
}

// 測試 + when 子句
void Test(int? age)
{
    try { ValidateAge(age); Console.WriteLine($"年齡 {age} 驗證通過"); }
    catch (ValidationException ex) when (ex is RequiredFieldException rf)
        => Console.WriteLine($"必填：{rf.FieldName}");
    catch (ValidationException ex) when (ex is ValueRangeException vr)
        => Console.WriteLine($"範圍錯誤：{vr.FieldName} 應在 {vr.Min}~{vr.Max}");
    catch (ValidationException ex)
        => Console.WriteLine($"驗證失敗：{ex.Message}");  // 其他 ValidationException
}
Test(null); Test(200); Test(25);

public class SafeFileReader : IDisposable
{
    private StreamReader? _reader;
    private bool _disposed = false;
    public string FilePath { get; }

    public SafeFileReader(string filePath)
    {
        FilePath = filePath;
        _reader = new StreamReader(filePath);
    }

    public string? ReadLine()
    {
        // 已 Dispose 後不可使用
        if (_disposed)
            throw new ObjectDisposedException(nameof(SafeFileReader),
                $"檔案讀取器 '{FilePath}' 已被釋放");

        return _reader?.ReadLine();
    }

    // IDisposable 實作
    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);  // 告訴 GC 不需呼叫 Finalizer
    }

    protected virtual void Dispose(bool disposing)
    {
        if (_disposed) return;  // 防止重複 Dispose

        if (disposing)
        {
            _reader?.Dispose();  // 釋放 managed 資源
            _reader = null;
        }
        _disposed = true;
    }
}

