public static void RetryWithCondition(
    Action operation,
    int maxRetries,
    Func<Exception, bool> shouldRetry)
{
    int attempt = 0;
    while (true)
    {
        try
        {
            attempt++;
            operation();
            return;  // 成功直接返回
        }
        catch (Exception ex) when (shouldRetry(ex) && attempt < maxRetries)
        {
            // when 子句：只有可重試且未超過次數時才進此 catch
            Console.WriteLine($"第 {attempt} 次失敗，重試中：{ex.Message}");
            Thread.Sleep(500 * attempt);  // 指數退避（簡化版）
        }
        catch (Exception ex) when (shouldRetry(ex) && attempt >= maxRetries)
        {
            throw new Exception($"重試 {maxRetries} 次後仍失敗", ex);
        }
        // 不符合 shouldRetry 條件的例外：直接穿透（不被捕捉）
    }
}

