// (1) try 有 return 時，finally 一定執行
public static int TestFinally()
{
    try
    {
        Console.WriteLine("try: 要 return 10");
        return 10;  // finally 仍會在 return 前執行
    }
    finally
    {
        Console.WriteLine("finally: 我執行了！");  // 這行會印出
        // 注意：finally 不能阻止 return，只是在 return 前執行
    }
}
// 輸出：try: 要 return 10
//       finally: 我執行了！
// 回傳值：10

// (2) finally 也有 return：finally 的 return 覆蓋 try 的 return
public static int FinallyOverridesReturn()
{
    try
    {
        return 10;  // 被 finally 的 return 覆蓋
    }
    finally
    {
        return 99;  // ⚠ 這會覆蓋 try 的回傳值（不建議這樣寫）
    }
}
// 回傳值：99（不是 10！）
// 編譯器會給警告：finally 中的 return 會吃掉 try 中的回傳值

// (3) async 方法的 finally
public static async Task<int> AsyncWithFinally()
{
    try
    {
        await Task.Delay(100);
        return 42;
    }
    finally
    {
        // async 方法的 finally 在 await 完成後、return 前執行
        Console.WriteLine("async finally 執行了");  // 一定會執行
        await Task.Delay(50);  // C# 也允許 finally 中 await（C# 6+）
    }
}

// 驗證
Console.WriteLine(TestFinally());           // 10
Console.WriteLine(FinallyOverridesReturn()); // 99（避免此寫法）
Console.WriteLine(AsyncWithFinally().Result); // 42

