exercises.answer:
// [修正方式一] 用 LINQ Where 過濾（最簡潔）
public static List<int> RemoveNegatives(List<int> numbers)
{
    return numbers.Where(n => n >= 0).ToList();
}

// [修正方式二] 反向 for 迴圈（從後往前刪除，索引不受影響）
public static List<int> RemoveNegativesFor(List<int> numbers)
{
    for (int i = numbers.Count - 1; i >= 0; i--)
    {
        if (numbers[i] < 0)
            numbers.RemoveAt(i);
    }
    return numbers;
}

// [修正方式三] 先收集要刪的、再刪
public static List<int> RemoveNegativesCollect(List<int> numbers)
{
    var toRemove = numbers.Where(n => n < 0).ToList();
    foreach (int n in toRemove)
        numbers.Remove(n);
    return numbers;
}

