public class IntStack
{
    private int[] _data = new int[10];
    private int _top = -1;  // [修正1] -1 表示空 Stack

    public bool IsEmpty => _top < 0;  // [修正1] 空時 _top 為 -1
    public int Count => _top + 1;

    public void Push(int item)
    {
        if (_top >= _data.Length - 1)
            throw new InvalidOperationException("Stack 已滿");
        _data[++_top] = item;  // 先加再寫：_top 先加 1 再指定
    }

    public int Pop()
    {
        if (IsEmpty) throw new InvalidOperationException("Stack 為空");
        // [修正2] 先讀頂端元素，再將 _top 減 1
        return _data[_top--];  // 後置 -- ：先取值再減
    }

    public int Peek()
    {
        if (IsEmpty) throw new InvalidOperationException("Stack 為空");
        return _data[_top];  // [修正2] 只讀不減
    }
}

