public static long CalculateFactorial(int n)
{
    if (n < 0) throw new ArgumentException("n 不可為負");
    if (n > 20) throw new ArgumentOutOfRangeException(nameof(n), "n 超過 long 的範圍（最大 20）");
    if (n == 0) return 1;

    // [修正] 用 long 累積乘積（long 最大約 9.2 × 10^18）
    long result = 1;
    for (int i = 1; i <= n; i++)
    {
        result *= i;
    }
    return result;

    // 若需要更大的數，用 BigInteger（System.Numerics）
    // checked 關鍵字讓整數溢位拋出 OverflowException（而非靜默）
    // checked { result *= i; }  ← 可用於偵測溢位
}

