public static void CountWords(string text)
{
    var wordCount = new Dictionary<string, int>();
    string[] words = text.Split(' ');

    foreach (string word in words)
    {
        // [修正方式一] ContainsKey 檢查
        if (wordCount.ContainsKey(word))
            wordCount[word]++;
        else
            wordCount[word] = 1;
    }

    // [修正方式二] TryGetValue（更有效率）
    var wordCount2 = new Dictionary<string, int>();
    foreach (string word in words)
    {
        if (wordCount2.TryGetValue(word, out int count))
            wordCount2[word] = count + 1;
        else
            wordCount2[word] = 1;
    }

    // [修正方式三] GetValueOrDefault（最簡潔）
    var wordCount3 = new Dictionary<string, int>();
    foreach (string word in words)
        wordCount3[word] = wordCount3.GetValueOrDefault(word, 0) + 1;

    foreach (var kvp in wordCount3)
        Console.WriteLine($"{kvp.Key}: {kvp.Value}");
}

