public class ListNode
{
    public int Val;
    public ListNode? Next;
    public ListNode(int val) { Val = val; }
}

public static ListNode? Reverse(ListNode? head)
{
    ListNode? prev = null;
    ListNode? curr = head;

    while (curr != null)
    {
        ListNode? next = curr.Next;  // 1. 先暫存下一個節點
        curr.Next = prev;            // 2. 反轉：讓 curr 指向 prev
        // [修正] 正確的移動順序
        prev = curr;                 // 3. prev 往前移到 curr
        curr = next;                 // 4. curr 往前移到 next
    }

    return prev;  // while 結束時 prev 是新的頭節點（原本的尾節點）
}

