public static void InOrder(TreeNode? root, List<int> result)
{
    if (root == null) return;

    // [修正] 中序：Left → Root → Right
    InOrder(root.Left, result);   // 1. 先遞迴左子樹
    result.Add(root.Val);          // 2. 再加入根節點
    InOrder(root.Right, result);  // 3. 最後遞迴右子樹
}

