public static void BubbleSort(int[] arr)
{
    int n = arr.Length;
    for (int i = 0; i < n; i++)  // 問題：外層應該是 n-1 次
    {
        for (int j = 0; j < n - 1; j++)  // 問題：內層應該是 n-1-i
        {
            if (arr[j] > arr[j + 1])
            {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
        // 沒有提前終止：即使已完全排序仍繼續
    }
}

exercises.answer:
public static void BubbleSort(int[] arr)
{
    int n = arr.Length;
    // [修正] 外層 n-1 次（最後一個元素不需比較）
    for (int i = 0; i < n - 1; i++)
    {
        bool swapped = false;  // [優化] 提前終止旗標

        // [修正] 每輪後，末尾 i 個元素已就位，不需再比
        for (int j = 0; j < n - 1 - i; j++)
        {
            if (arr[j] > arr[j + 1])
            {
                (arr[j], arr[j + 1]) = (arr[j + 1], arr[j]);  // tuple swap
                swapped = true;
            }
        }

        // [優化] 若本輪沒有交換，陣列已排序完成
        if (!swapped) break;
    }
}

// 測試
int[] arr = { 5, 3, 8, 1, 9, 2 };
BubbleSort(arr);
Console.WriteLine(string.Join(", ", arr));  // 1, 2, 3, 5, 8, 9

