exercises.answer:
public static List<string> GetMatchingFiles(List<string> filePaths, string keyword)
{
    // [修正] 先用 Select 投影成含 Size 的匿名型別，避免重複 IO
    return filePaths
        .Select(p => new { Path = p, Size = GetFileSize(p) })  // 每個檔案只讀一次
        .Where(x => x.Size > 1000 && x.Path.Contains(keyword))
        .OrderByDescending(x => x.Size)
        .Select(x => x.Path)  // 最後只取路徑
        .ToList();
}

// 更好的寫法：先過濾 Contains（便宜操作），再做 IO（昂貴操作）
public static List<string> GetMatchingFilesOptimized(List<string> filePaths, string keyword)
{
    return filePaths
        .Where(p => p.Contains(keyword))  // 先過濾（便宜）
        .Select(p => new { Path = p, Size = GetFileSize(p) })  // 再 IO（只對符合的）
        .Where(x => x.Size > 1000)
        .OrderByDescending(x => x.Size)
        .Select(x => x.Path)
        .ToList();
}

